package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.function.Function;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGrades;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * The figures of one person's claims, as the screen works them out: a settled claim's frozen due, else the
 * figure its person's last statement bound it to, else its live due (amount times the rate in force on its date of
 * the grade its person had on its date, rounded by the sheet's policy; none — n/a — when no rate applies then, or the one that would has ended by then). An
 * overdue claim's due adds, on top of its figure, the late charge: for each full 30 days it is overdue on the sheet's today, the
 * sheet's late percent in force on that boundary date (its due-by plus its grade's grace, plus 30, 60, 90 ... days) of the figure plus
 * the charges of the boundaries before it (compounding), rounded like a due, and
 * the charges added up (a boundary whose percent is 0.00 adds nothing). The floor comes first: an unsettled claim's due is the
 * greater of the sheet's floor in force on its date and its figure (the floored figure), plus the late charge worked out on that
 * floored figure. A statement binds the due as shown (the floored figure and its late charge), which then no longer follows the sheet's today; settling freezes the due in. A correction's live due is its amount times the rate, rounded the same way, with no floor, and it
 * never takes a late charge. The rounding policy: a claim dated before the sheet's policy date (its today when blank)
 * rounds half up, one dated on or after it half to even — unless the sheet has a rounding mode (half-up or half-even) in force on
 * that date, which it then rounds by; a correction goes by the date of the claim it corrects.
 */
public class ClaimFigures {

    private final List<Rate> rates;

    private final PersonGrades grades;

    private final Sheet sheet;

    private final LocalDate today;

    private final LocalDate policyDate;

    private Function<Long, PersonGrades> holders = id -> null;

    /** @param rates the sheet's rates.
     *  @param grades the person's grades over time.
     *  @param sheet the sheet: its floor on a claim's date (a live due is at least it), and its late percent on each
     *  30-day boundary of a claim's due-by up to its today (the late charge), and its cap in force on the date of a person's latest claim that counts. */
    public ClaimFigures(List<Rate> rates, PersonGrades grades, Sheet sheet) {
        this.rates = rates;
        this.grades = grades;
        this.sheet = sheet;
        this.today = sheet.getToday();
        this.policyDate = sheet.policyDateInForce();
    }

    /** Gives the grades over time of a holder of a share, by their person id (null: not known — no rate applies
     *  to them), for the holders' parts; returns these figures. */
    public ClaimFigures withHolders(Function<Long, PersonGrades> holders) {
        this.holders = holders;
        return this;
    }

    /** A holder's part of a claim whose due is given: a settled claim's frozen part, its frozen due times their share
     *  divided by 100, rounded half to even; else its amount times their share divided by 100, times the rate in force
     *  on its date of the grade the holder had on its date divided by 100, rounded like the claim; null when that
     *  grade has no rate then (the part counts as 0.00). */
    public BigDecimal part(Claim claim, BigDecimal due, ClaimShares.Share share) {
        if (claim.getDue() != null) {
            return ClaimShares.part(due, share.share());
        }
        PersonGrades holder = holders.apply(share.personId());
        if (holder == null) {
            return null;
        }
        return rateOn(holder.on(claim.getDate()), claim)
                .map(pct -> claim.getAmount().multiply(share.share()).multiply(pct).movePointLeft(4)
                        .setScale(2, rounding(claim)))
                .orElse(null);
    }

    /** The holders' parts of a claim whose due is given, added up (0.00 with none). */
    public BigDecimal parts(Claim claim, BigDecimal due) {
        return ClaimShares.of(claim).stream().map(s -> part(claim, due, s)).filter(p -> p != null)
                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
    }

    /** How the claim's live figures round: by the sheet's rounding mode in force on the date it rounds by, when one
     *  is; else half up when that date is before the policy date, else half to even. */
    public RoundingMode rounding(Claim claim) {
        String mode = sheet.roundingOn(claim.getRoundsOn());
        if (Sheet.HALF_UP.equals(mode)) {
            return RoundingMode.HALF_UP;
        }
        if (Sheet.HALF_EVEN.equals(mode)) {
            return RoundingMode.HALF_EVEN;
        }
        return claim.getRoundsOn().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The date a claim's lateness counts from: its due-by (fixed when it was created) plus the grace days in force on
     *  its date of the grade its person had on its date (none: its due-by). */
    public LocalDate lateFrom(Claim claim) {
        Integer grace = sheet.gradeGraceOn(grades.on(claim.getDate()), claim.getDate());
        return grace == null ? claim.getDueBy() : claim.getDueBy().plusDays(grace);
    }

    /** Whether a claim is overdue: it is OPEN or PENDING, not deferred, and its due-by plus any grace of its grade
     *  ({@link #lateFrom}) is before the sheet's today. */
    public boolean overdue(Claim claim) {
        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && lateFrom(claim).isBefore(today);
    }

    /** The late charge on a figure: for each full 30 days the claim is overdue, the late percent in force on that
     *  boundary date of it plus the charges before it, rounded like its due, added up; 0.00 when it is not overdue,
     *  or its late charge is waived. */
    public BigDecimal lateCharge(Claim claim, BigDecimal figure) {
        if (figure == null || claim.isCorrection() || claim.isWaived() || !overdue(claim)) {
            return BigDecimal.ZERO.setScale(2);
        }
        return chargeByBoundary(claim, figure);
    }

    /** The late percent in force on each full 30-day boundary past the claim's due-by plus any grace
     *  ({@link #lateFrom}), up to the sheet's today, of the figure plus the charges of the boundaries before it, each
     *  rounded like its due, added up. */
    private BigDecimal chargeByBoundary(Claim claim, BigDecimal figure) {
        LocalDate from = lateFrom(claim);
        long periods = ChronoUnit.DAYS.between(from, today) / 30;
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        for (long k = 1; k <= periods; k++) {
            BigDecimal pct = sheet.latePctOn(from.plusDays(30 * k));
            if (pct.signum() != 0) {
                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding(claim)));
            }
        }
        return charge;
    }

    /** A rate figure: the amount times the percent, divided by 100, rounded as given. */
    public static BigDecimal rateFigure(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
    }

    /** The floor, applied before the late charge: the greater of the sheet's floor in force on the claim's date and
     *  the given figure; a correction takes no floor. */
    private BigDecimal floored(Claim claim, BigDecimal due) {
        if (claim.isCorrection()) {
            return due;
        }
        BigDecimal floor = sheet.floorOn(claim.getDate());
        return floor != null && due.compareTo(floor) < 0 ? floor.setScale(2) : due;
    }

    /** Whether a claim counts toward the totals on a day: only OPEN, PENDING and SETTLED claims do, but not one
     *  deferred until after that day ({@link Claim#isDeferredOn}: a bound one's deferral waits for its binding to end). */
    public static boolean counts(Claim claim, LocalDate today) {
        return (claim.getStatus().isOpen() || claim.getStatus() == ClaimStatus.SETTLED) && !claim.isDeferredOn(today);
    }

    /** Whether a claim counts toward the live totals: as {@link #counts}, except its person's OPEN and PENDING
     *  claims once their retirement date is reached, unless a statement binds them (null person: not retired). */
    public static boolean countsLive(Claim claim, Person person, LocalDate today) {
        return counts(claim, today) && !(claim.getStatus().isOpen() && !claim.isBound() && leftOn(claim, person, today));
    }

    /** Whether a claim counts toward claimed: as {@link #countsLive}, except a hold (the claim's or its person's)
     *  does not take it out; only its person's retirement date being reached does (null person: not retired). */
    public static boolean countsClaimed(Claim claim, Person person, LocalDate today) {
        return counts(claim, today) && !(claim.getStatus().isOpen() && !claim.isBound()
                && person != null && person.retiredBy(today));
    }

    /** Whether a claim counts toward a period's live totals: as {@link #countsLive}, taking the status it had at the
     *  end of the period's last day (null: it had not been added by then, so it does not count); a hold takes out
     *  only a claim that is still OPEN or PENDING and unbound now. */
    public static boolean countsAsOf(Claim claim, ClaimStatus then, Person person, LocalDate today) {
        if (then == null || !(then.isOpen() || then == ClaimStatus.SETTLED)) {
            return false;
        }
        boolean deferred = claim.isDeferralOn(then, today);
        return !deferred && !(claim.getStatus().isOpen() && !claim.isBound() && leftOn(claim, person, today));
    }

    /** Whether the claim, while OPEN or PENDING and unbound, leaves the live totals on the day: its person's
     *  retirement date is reached (null person: not retired). A hold, the claim's or its person's, does not take it
     *  out; it only denies its person a pool cut. */
    private static boolean leftOn(Claim claim, Person person, LocalDate today) {
        return person != null && person.retiredBy(today);
    }

    /** The percent of the grade's rate in force on a date; none when that rate's to-date is before it. When the
     *  sheet has none in force then, the next sheet up its chain's (the rates of each sheet come in chain order). */
    private Optional<BigDecimal> rateOn(String grade, LocalDate on) {
        return rateOn(grade, on, rates);
    }

    /** The percent of the grade's rate that applies to the claim on its date, as {@link #rateOn(String, LocalDate)}:
     *  a forward-only rate saved after the claim was added does not apply to it ({@link Rate#forClaim}). */
    private Optional<BigDecimal> rateOn(String grade, Claim claim) {
        return rateOn(grade, claim.getDate(), rates.stream().flatMap(r -> r.forClaim(claim.getId()).stream()).toList());
    }

    private static Optional<BigDecimal> rateOn(String grade, LocalDate on, List<Rate> rates) {
        List<String> chain = new ArrayList<>();
        rates.stream().map(Rate::getSheetId).filter(id -> !chain.contains(id)).forEach(chain::add);
        for (String sheetId : chain) {
            Optional<BigDecimal> pct = rates.stream()
                    .filter(r -> r.getSheetId().equals(sheetId) && r.getGrade().equals(grade))
                    .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(on))
                    .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                    .filter(r -> !r.endedBy(on))
                    .map(Rate::getPct);
            if (pct.isPresent()) {
                return pct;
            }
        }
        return Optional.empty();
    }

    /** The due the claim would have today as an open claim bound by no statement: its live figure at today's rates,
     *  grades and floor, plus the late charge it would carry on that as an open claim; null when it has none (n/a). */
    public BigDecimal openDue(Claim claim) {
        BigDecimal figure = liveFigure(claim);
        if (figure == null) {
            return null;
        }
        if (claim.isCorrection() || claim.isWaived() || !lateFrom(claim).isBefore(today)) {
            return floored(claim, figure);
        }
        BigDecimal floored = floored(claim, figure);
        return floored.add(chargeByBoundary(claim, floored));
    }

    /** The claim's due: its frozen due when settled, else the due its person's last statement bound it to, else the
     *  greater of its floor and its figure, plus the late charge worked out on that; null when it has none (n/a). */
    public BigDecimal due(Claim claim) {
        if (claim.getDue() != null) {
            return claim.getDue();
        }
        if (claim.isBound()) {
            return claim.getStatedDue();
        }
        BigDecimal figure = figure(claim);
        if (figure == null) {
            return null;
        }
        BigDecimal floored = floored(claim, figure);
        return floored.add(lateCharge(claim, floored));
    }

    /** The claim's figure, without any late charge or floor (a bound claim's: the due it is bound to); null when it
     *  has none (n/a). */
    public BigDecimal figure(Claim claim) {
        if (claim.getDue() != null) {
            return claim.getDue();
        }
        if (claim.isBound()) {
            return claim.getStatedDue();
        }
        return liveFigure(claim);
    }

    /** The claim's live figure: neither frozen nor bound; null when it has none (n/a). */
    private BigDecimal liveFigure(Claim claim) {
        return rateOn(grades.on(claim.getDate()), claim)
                .map(pct -> rateFigure(claim.getAmount(), pct, rounding(claim)))
                .orElse(null);
    }

    /** The claim's due less its holders' parts ({@link #part}): what its own person's due-total counts of it; null
     *  when it has none (n/a). */
    public BigDecimal ownDue(Claim claim) {
        BigDecimal due = due(claim);
        return due == null ? null : due.subtract(parts(claim, due));
    }

    /** The person's due-total: their counted claims' dues (with any late charge) added up, 0.00 with none; n/a when their grade
     *  in force on the day has no rate in force then, unless a counted claim keeps a figure: a fixed one (settled or bound), or a
     *  live one at another grade they had on its date, or one dated on or before the day (at a rate that has ended since). */
    public String dueTotal(List<Claim> claims, LocalDate today) {
        return dueTotal(claims, today, null);
    }

    /** The person's live due-total, as {@link #dueTotal(List, LocalDate)}; their OPEN claims do not count once their
     *  retirement date is reached, unless a statement binds them. At most the sheet's cap (n/a is not capped). */
    public String dueTotal(List<Claim> claims, LocalDate today, Person person) {
        return dueTotal(claims, today, person, null);
    }

    /** The person's live due-total, as {@link #dueTotal(List, LocalDate, Person)}, with their parts of the claims of
     *  others shared with them (null: they hold no share of a counted claim) added before the cap: their own claims
     *  count less the holders' parts, and when they would have none (n/a) their parts are their due-total. */
    public String dueTotal(List<Claim> claims, LocalDate today, Person person, BigDecimal held) {
        return dueTotal(claims, today, person, held, null);
    }

    /** The person's live due-total, as {@link #dueTotal(List, LocalDate, Person, BigDecimal)}, with the cap covering
     *  it plus their cut total (null: none): it is held to the cap less their cut total, not below 0.00. Their cap is
     *  the one in force on the date of their latest claim that counts (the sheet's today when none counts). */
    public String dueTotal(List<Claim> claims, LocalDate today, Person person, BigDecimal held, BigDecimal cut) {
        String sum = uncappedDueTotal(claims, today, person);
        BigDecimal cap = sheet.capOn(claims.stream().filter(c -> countsLive(c, person, today)).map(Claim::getDate)
                .max(Comparator.naturalOrder()).orElse(today));
        if (held != null) {
            sum = ("n/a".equals(sum) ? held : new BigDecimal(sum).add(held)).setScale(2).toPlainString();
        }
        if (cap == null || "n/a".equals(sum)) {
            return sum;
        }
        BigDecimal limit = cut == null ? cap : cap.subtract(cut).max(BigDecimal.ZERO);
        if (new BigDecimal(sum).compareTo(limit) <= 0) {
            return sum;
        }
        return limit.setScale(2).toPlainString();
    }

    /** The person's live due-total before the cap: the sum of their figures. */
    private String uncappedDueTotal(List<Claim> claims, LocalDate today, Person person) {
        List<Claim> counted = claims.stream().filter(c -> countsLive(c, person, today)).toList();
        String grade = grades.on(today);
        boolean kept = counted.stream().anyMatch(c -> c.getDue() != null || (c.isBound() && c.getStatedDue() != null)
                || (!c.isBound() && (!grade.equals(grades.on(c.getDate())) || !c.getDate().isAfter(today)) && figure(c) != null));
        if (rateOn(grade, today).isEmpty() && !kept) {
            return "n/a";
        }
        return counted.stream().map(this::ownDue).filter(f -> f != null)
                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;

/** The claim form's rules, shared by the steps that add claims one at a time and many at once. */
public final class ClaimRules {

    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");

    private static final Pattern NUMBER = Pattern.compile("(.+-)?\\d{1,9}");

    private ClaimRules() {
    }

    /** Checks one claim form's fields, with no tags, as ValidateClaim does; a null field is blank. */
    public static ClaimInput check(String amountField, String dateField, String noteField, String correctsField,
            String refField) throws InvalidClaimException {
        return check(amountField, dateField, noteField, correctsField, refField, null);
    }

    /** Checks one claim form's fields as ValidateClaim does; a null field is blank. */
    public static ClaimInput check(String amountField, String dateField, String noteField, String correctsField,
            String refField, String tagsField) throws InvalidClaimException {
        String amount = amountField == null ? "" : amountField.trim();
        String date = dateField == null ? "" : dateField.trim();
        String note = noteField == null ? "" : noteField.trim();
        String corrects = correctsField == null ? "" : correctsField.trim();
        String ref = refField == null ? "" : refField.trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
        }
        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("Corrects must be a claim number.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        if (value.signum() < 0 && corrects.isEmpty()) {
            throw new InvalidClaimException("A negative amount is a correction: name the settled claim it corrects.");
        }
        if (value.signum() >= 0 && !corrects.isEmpty()) {
            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim.");
        }
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("Not a date: " + date);
            }
        }
        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects,
                ref.isEmpty() ? null : ref, Tags.normalise(tagsField));
    }

    /** The claim the input makes for the person, not yet saved; refused as BuildClaim refuses it. Its due-by is the
     *  terms-th business day after its date (the terms of the person's grade on its date, in force on the
     *  sheet's today, the day it is created), skipping weekends and the sheet's holidays now on its list. */
    public static Claim make(ClaimInput input, Sheet sheet, Person person, ClaimRepository repository,
            PeriodRepository periods, PersonGradeRepository grades, HolidayRepository holidays) throws InvalidClaimException {
        LocalDate date = input.date() != null ? input.date() : sheet.entryDateInForce();
        LocalDate created = sheet.getToday();
        int terms = sheet.termsFor(person.termsOn(created), grades.gradesOf(person).on(date), created);
        LocalDate dueBy = holidays.dueBy(sheet.getId(), date, terms);
        if (periods.isClosedOn(sheet.getId(), dueBy)) {
            throw new InvalidClaimException("No claim can be added in a closed period.");
        }
        if (person.retiredOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
        }
        LocalDate correctsDate = repository.checkCorrects(sheet.getId(), person.getId(), input.corrects(),
                input.amount(), null);
        repository.checkRef(sheet.getId(), null, input.ref());
        Claim claim = new Claim(sheet.getId(), person.getId(), input.amount(), date, input.note(), input.corrects());
        claim.setCorrectsDate(correctsDate);
        claim.setRef(input.ref());
        claim.setTags(input.tags());
        claim.setLateEntry(periods.isSoftClosedOn(sheet.getId(), dueBy));
        claim.fixDue(date, terms, holidays.datesOf(sheet.getId()));
        return claim;
    }

    /** Records the claim's adding (its ref, then its tags, at the end, when it has them), and after it, when it is a late entry, its LATE_ENTRY. */
    public static void auditAdded(Claim claim, String personName, String by, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_ADDED", claim, personName, by)
                + (claim.getRef() == null ? "" : " ref=" + claim.getRef())
                + (claim.getTags() == null ? "" : " tags=" + claim.getTags()));
        if (claim.isLateEntry()) {
            audit.record(ClaimAudit.line("LATE_ENTRY", claim, personName, by));
        }
    }

    /** Writes the claim's status log entry as LogClaimStatus does, made by the given user. */
    public static void log(Claim claim, Sheet sheet, ClaimLogRepository log, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, String by) {
        BigDecimal due = people.findById(claim.getPersonId())
                .map(p -> new ClaimFigures(rates.findInChain(claim.getSheetId()),
                        grades.gradesOf(p), sheet).due(claim))
                .orElse(null);
        log.saveAndFlush(new ClaimLog(claim, by, sheet.getToday(), due));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Locale;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.Sheet;

/** The person form's rules, shared by the form and the people import box. */
public final class PersonRules {

    private static final Pattern TERMS = Pattern.compile("\\d{1,5}");

    private PersonRules() {
    }

    /**
     * Checks the form's fields, trimming the name; refuses an empty name or a grade not shaped as one (the sheet's grades are checked by refuseRetired), a grade
     * from-date that is not a calendar date, and terms that are not a whole number of days; the contact is trimmed
     * and lower-cased; the tags are normalised as Tags.normalise does.
     */
    /** Checks the terms from-date: trimmed, blank allowed, otherwise a calendar date. */
    public static String checkTermsFrom(String termsFrom) throws InvalidPersonException {
        termsFrom = termsFrom == null ? "" : termsFrom.trim();
        if (!termsFrom.isEmpty()) {
            try {
                LocalDate.parse(termsFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date: " + termsFrom);
            }
        }
        return termsFrom;
    }

    public static PersonRequest check(String name, String grade, Long version, String gradeFrom, String terms,
            String contact, String tags) throws InvalidPersonException {
        name = name == null ? "" : name.trim();
        grade = grade == null ? "" : grade.trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (!net.officefloor.hq.app.grade.RetiredGrades.isCode(grade)) {
            throw new InvalidPersonException("The grade must be one of the sheet's grades.");
        }
        gradeFrom = gradeFrom == null ? "" : gradeFrom.trim();
        if (!gradeFrom.isEmpty()) {
            try {
                LocalDate.parse(gradeFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date: " + gradeFrom);
            }
        }
        terms = terms == null ? "" : terms.trim();
        if (!terms.isEmpty() && !TERMS.matcher(terms).matches()) {
            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more, or blank.");
        }
        contact = contact == null ? "" : contact.trim().toLowerCase(Locale.ROOT);
        return new PersonRequest(name, grade, version, gradeFrom, terms, contact,
                net.officefloor.hq.app.claim.Tags.normalise(tags));
    }

    /**
     * Makes the person to add to the sheet, unsaved: refused when the name is a name or alias on the sheet or on
     * another sheet of its tree, ignoring case, or the contact is another person's on the sheet.
     */
    public static Person make(PersonRequest request, Sheet sheet, PersonRepository repository,
            PersonAliasRepository aliases, TreeNames tree) throws InvalidPersonException {
        if (repository.existsBySheetIdAndNameIgnoreCase(sheet.getId(), request.name())
                || aliases.existsBySheetIdAndAliasIgnoreCase(sheet.getId(), request.name())) {
            throw new InvalidPersonException("The name is already in use on this sheet.");
        }
        if (tree.usedAround(sheet.getId(), request.name())) {
            throw new InvalidPersonException("The name is already in use on a sheet of this sheet's tree.");
        }
        if (request.contactOrNull() != null
                && repository.existsBySheetIdAndContact(sheet.getId(), request.contactOrNull())) {
            throw new InvalidPersonException("The contact is already in use on this sheet.");
        }
        Person person = new Person(sheet.getId(), request.name(), request.grade());
        person.setAddedOn(sheet.getToday());
        if (request.termsFromDate() == null) {
            person.setTerms(request.termsDays());
        } else {
            person.setTermsFrom(request.termsFromDate(), request.termsDays());
        }
        person.setContact(request.contactOrNull());
        person.setTags(request.tags());
        return person;
    }

    /** Refuses a grade not one of the sheet's grades, and one retired on the sheet: people on it keep it, but it
     *  cannot be chosen for a new person or in an edit. */
    public static void refuseRetired(String sheetId, String grade,
            net.officefloor.hq.app.grade.RetiredGradeRepository retired,
            net.officefloor.hq.app.grade.AddedGradeRepository added) throws InvalidPersonException {
        if (!net.officefloor.hq.app.grade.RetiredGrades.isGrade(sheetId, grade, added)) {
            throw new InvalidPersonException("The grade must be one of the sheet's grades.");
        }
        if (net.officefloor.hq.app.grade.RetiredGrades.isRetired(sheetId, grade, retired)) {
            throw new InvalidPersonException("The grade " + grade + " is retired.");
        }
    }

    /** The PERSON_ADDED record for the added person: their terms when they have any, their contact when they have one. */
    public static String addedLine(Person person, String by) {
        return "PERSON_ADDED sheet=" + person.getSheetId() + " by=" + by
                + " name=" + person.getName() + " grade=" + person.getGrade()
                + (person.getTerms() == null ? "" : " terms=" + person.getTerms())
                + (person.getContact() == null ? "" : " contact=" + person.getContact());
    }

