200	    private Optional<BigDecimal> rateOn(String grade, Claim claim) {
201	        return rateOn(grade, claim.getDate(), rates.stream().flatMap(r -> r.forClaim(claim.getId()).stream()).toList());
202	    }
203	
204	    private static Optional<BigDecimal> rateOn(String grade, LocalDate on, List<Rate> rates) {
205	        List<String> chain = new ArrayList<>();
206	        rates.stream().map(Rate::getSheetId).filter(id -> !chain.contains(id)).forEach(chain::add);
207	        for (String sheetId : chain) {
208	            Optional<BigDecimal> pct = rates.stream()
209	                    .filter(r -> r.getSheetId().equals(sheetId) && r.getGrade().equals(grade))
210	                    .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(on))
211	                    .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
212	                    .filter(r -> !r.endedBy(on))
213	                    .map(Rate::getPct);
214	            if (pct.isPresent()) {
215	                return pct;
216	            }
217	        }
218	        return Optional.empty();
219	    }
