223	    public BigDecimal openDue(Claim claim) {
224	        BigDecimal figure = liveFigure(claim);
225	        if (figure == null) {
226	            return null;
227	        }
228	        if (claim.isCorrection() || claim.isWaived() || !lateFrom(claim).isBefore(today)) {
229	            return floored(claim, figure);
230	        }
231	        BigDecimal floored = floored(claim, figure);
232	        return floored.add(chargeByBoundary(claim, floored));
233	    }
