236	     *  greater of its floor and its figure, plus the late charge worked out on that; null when it has none (n/a). */
237	    public BigDecimal due(Claim claim) {
238	        if (claim.getDue() != null) {
239	            return claim.getDue();
240	        }
241	        if (claim.isBound()) {
242	            return claim.getStatedDue();
243	        }
244	        BigDecimal figure = figure(claim);
245	        if (figure == null) {
246	            return null;
247	        }
248	        BigDecimal floored = floored(claim, figure);
249	        return floored.add(lateCharge(claim, floored));
250	    }
