252	    /** The claim's figure, without any late charge or floor (a bound claim's: the due it is bound to); null when it
253	     *  has none (n/a). */
254	    public BigDecimal figure(Claim claim) {
255	        if (claim.getDue() != null) {
256	            return claim.getDue();
257	        }
258	        if (claim.isBound()) {
259	            return claim.getStatedDue();
260	        }
261	        return liveFigure(claim);
262	    }
263	
264	    /** The claim's live figure: neither frozen nor bound; null when it has none (n/a). */
265	    private BigDecimal liveFigure(Claim claim) {
266	        return rateOn(grades.on(claim.getDate()), claim)
267	                .map(pct -> rateFigure(claim.getAmount(), pct, rounding(claim)))
268	                .orElse(null);
269	    }
