271	    /** The claim's due less its holders' parts ({@link #part}): what its own person's due-total counts of it; null
272	     *  when it has none (n/a). */
273	    public BigDecimal ownDue(Claim claim) {
274	        BigDecimal due = due(claim);
275	        return due == null ? null : due.subtract(parts(claim, due));
276	    }
277	
278	    /** The person's due-total: their counted claims' dues (with any late charge) added up, 0.00 with none; n/a when their grade
279	     *  in force on the day has no rate in force then, unless a counted claim keeps a figure: a fixed one (settled or bound), or a
280	     *  live one at another grade they had on its date, or one dated on or before the day (at a rate that has ended since). */
281	    public String dueTotal(List<Claim> claims, LocalDate today) {
282	        return dueTotal(claims, today, null);
283	    }
284	
285	    /** The person's live due-total, as {@link #dueTotal(List, LocalDate)}; their OPEN claims do not count once their
286	     *  retirement date is reached, unless a statement binds them. At most the sheet's cap (n/a is not capped). */
287	    public String dueTotal(List<Claim> claims, LocalDate today, Person person) {
288	        return dueTotal(claims, today, person, null);
289	    }
290	
291	    /** The person's live due-total, as {@link #dueTotal(List, LocalDate, Person)}, with their parts of the claims of
292	     *  others shared with them (null: they hold no share of a counted claim) added before the cap: their own claims
293	     *  count less the holders' parts, and when they would have none (n/a) their parts are their due-total. */
294	    public String dueTotal(List<Claim> claims, LocalDate today, Person person, BigDecimal held) {
295	        return dueTotal(claims, today, person, held, null);
296	    }
297	
298	    /** The person's live due-total, as {@link #dueTotal(List, LocalDate, Person, BigDecimal)}, with the cap covering
299	     *  it plus their cut total (null: none): it is held to the cap less their cut total, not below 0.00. Their cap is
300	     *  the one in force on the date of their latest claim that counts (the sheet's today when none counts). */
301	    public String dueTotal(List<Claim> claims, LocalDate today, Person person, BigDecimal held, BigDecimal cut) {
302	        String sum = uncappedDueTotal(claims, today, person);
303	        BigDecimal cap = sheet.capOn(claims.stream().filter(c -> countsLive(c, person, today)).map(Claim::getDate)
304	                .max(Comparator.naturalOrder()).orElse(today));
305	        if (held != null) {
306	            sum = ("n/a".equals(sum) ? held : new BigDecimal(sum).add(held)).setScale(2).toPlainString();
307	        }
308	        if (cap == null || "n/a".equals(sum)) {
309	            return sum;
310	        }
311	        BigDecimal limit = cut == null ? cap : cap.subtract(cut).max(BigDecimal.ZERO);
312	        if (new BigDecimal(sum).compareTo(limit) <= 0) {
313	            return sum;
314	        }
315	        return limit.setScale(2).toPlainString();
316	    }
317	
318	    /** The person's live due-total before the cap: the sum of their figures. */
319	    private String uncappedDueTotal(List<Claim> claims, LocalDate today, Person person) {
320	        List<Claim> counted = claims.stream().filter(c -> countsLive(c, person, today)).toList();
321	        String grade = grades.on(today);
322	        boolean kept = counted.stream().anyMatch(c -> c.getDue() != null || (c.isBound() && c.getStatedDue() != null)
323	                || (!c.isBound() && (!grade.equals(grades.on(c.getDate())) || !c.getDate().isAfter(today)) && figure(c) != null));
324	        if (rateOn(grade, today).isEmpty() && !kept) {
325	            return "n/a";
326	        }
327	        return counted.stream().map(this::ownDue).filter(f -> f != null)
328	                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2).toPlainString();
329	    }
