9	/** The person form's rules, shared by the form and the people import box. */
10	public final class PersonRules {
11	
12	    private static final Pattern TERMS = Pattern.compile("\\d{1,5}");
13	
14	    private PersonRules() {
15	    }
16	
17	    /**
18	     * Checks the form's fields, trimming the name; refuses an empty name or a grade not shaped as one (the sheet's grades are checked by refuseRetired), a grade
19	     * from-date that is not a calendar date, and terms that are not a whole number of days; the contact is trimmed
20	     * and lower-cased; the tags are normalised as Tags.normalise does.
21	     */
22	    /** Checks the terms from-date: trimmed, blank allowed, otherwise a calendar date. */
23	    public static String checkTermsFrom(String termsFrom) throws InvalidPersonException {
24	        termsFrom = termsFrom == null ? "" : termsFrom.trim();
25	        if (!termsFrom.isEmpty()) {
26	            try {
27	                LocalDate.parse(termsFrom);
28	            } catch (DateTimeParseException e) {
29	                throw new InvalidPersonException("Not a date: " + termsFrom);
30	            }
31	        }
32	        return termsFrom;
33	    }
34	
35	    public static PersonRequest check(String name, String grade, Long version, String gradeFrom, String terms,
36	            String contact, String tags) throws InvalidPersonException {
37	        name = name == null ? "" : name.trim();
38	        grade = grade == null ? "" : grade.trim();
39	        if (name.isEmpty()) {
40	            throw new InvalidPersonException("A name is required.");
41	        }
42	        if (!net.officefloor.hq.app.grade.RetiredGrades.isCode(grade)) {
43	            throw new InvalidPersonException("The grade must be one of the sheet's grades.");
44	        }
45	        gradeFrom = gradeFrom == null ? "" : gradeFrom.trim();
46	        if (!gradeFrom.isEmpty()) {
47	            try {
48	                LocalDate.parse(gradeFrom);
49	            } catch (DateTimeParseException e) {
50	                throw new InvalidPersonException("Not a date: " + gradeFrom);
51	            }
52	        }
53	        terms = terms == null ? "" : terms.trim();
54	        if (!terms.isEmpty() && !TERMS.matcher(terms).matches()) {
55	            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more, or blank.");
56	        }
57	        contact = contact == null ? "" : contact.trim().toLowerCase(Locale.ROOT);
58	        return new PersonRequest(name, grade, version, gradeFrom, terms, contact,
59	                net.officefloor.hq.app.claim.Tags.normalise(tags));
60	    }
61	
