25	    24	            case "reject" -> this == PENDING ? OPEN : null;
26	    25	            case "void" -> this == DRAFT || this == REVIEW || this == OPEN || this == PENDING || this == SETTLED ? VOID : null;
27	    26	            case "delete" -> this == DRAFT ? DELETED : null;
28	    27	            case "restore" -> this == DELETED ? DRAFT : null;
