  278	    /** The next number in the claim's sequence as it is settled now: within the period its due-by falls in
  279	     *  (<period>-<n>, X-<n> in none) while the sheet's period numbering is on, else in the fiscal year of its due-by
  280	     *  (FY<year>-<n>, shared across the sheet's tree). Locks the sheet (or tree) first, so two claims settled at once
  281	     *  are numbered one after the other. */
  282	    private static String takeNumber(Claim claim, ClaimRepository repository, PeriodRepository periods, Sheet sheet) {
  283	        if (sheet.periodNumberingOn()) {
  284	            repository.lockSheet(claim.getSheetId());
  285	            String prefix = periods.findBySheetIdOrderByFromDateAscIdAsc(claim.getSheetId()).stream()
  286	                    .filter(p -> p.contains(claim.getDueBy())).map(Period::getName).findFirst().orElse(null);
  287	            String seq = prefix == null ? "X" : "P:" + prefix;
  288	            return (prefix == null ? "X" : prefix) + "-" + repository.takeNextInSequence(claim.getSheetId(), seq);
  289	        }
  290	        repository.lockTree(claim.getSheetId());
  291	        return repository.takeNextInFiscalYear(claim.getSheetId(), sheet.getFiscalStartMonth(), claim.getDueBy());
  292	    }
  293	
  294	    private static ClaimStatus check(Claim claim, String action) throws ClaimStatusException {
  295	        ClaimStatus next = claim.getStatus().after(action);
  296	        if (next == null) {
  297	            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot " + action + ".");
  298	        }
  299	        return next;
  300	    }
