     8	/**
     9	 * Reminds an OPEN or PENDING claim: its reminded date becomes the sheet's today. A claim in any other status, or one
    10	 * already reminded on the sheet's today, is refused. With the sheet's escalation gap set, a claim never escalated
    11	 * whose previous reminder was at least that many days before the sheet's today is escalated.
    12	 */
    13	public class ApplyRemind {
    14	    public void apply(@Val Claim claim, @Val Sheet sheet, ClaimRepository repository, Out<Escalation> escalation)
    15	            throws ClaimStatusException {
    16	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
    17	            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be reminded.");
    18	        }
    19	        if (sheet.getToday().equals(claim.getRemindedOn())) {
    20	            throw new ClaimStatusException("This claim was already reminded on " + sheet.getToday() + ".");
    21	        }
    22	        Integer gap = sheet.getEscalateAfter();
    23	        boolean escalate = gap != null && !claim.isEscalated() && claim.getRemindedOn() != null
    24	                && ChronoUnit.DAYS.between(claim.getRemindedOn(), sheet.getToday()) >= gap;
    25	        if (escalate) {
    26	            claim.setEscalated(true);
    27	        }
    28	        claim.setRemindedOn(sheet.getToday());
    29	        repository.saveAndFlush(claim);
    30	        escalation.set(new Escalation(escalate));
    31	    }
    32	}

