    15	/**
    16	 * Re-settles a SETTLED claim: freezes its due again at the figure it would have today as an open claim bound by no
    17	 * statement (today's rates, grades, floor and late charge; n/a leaves it live). Only a steward re-settles, and a claim
    18	 * whose due-by is in a closed period, or in any other status, cannot be. Returns the due it had before, for the audit.
    19	 */
    20	public class ApplyResettle {
    21	    public Resettled apply(@Val Claim claim, @Val Sheet sheet, ClaimRepository repository, PersonRepository people,
    22	            RateRepository rates, PersonGradeRepository grades, PeriodRepository periods, RoleRepository roles,
    23	            @RequestHeader(name = "X-User", required = false) String userHeader)
    24	            throws ClaimStatusException, ClerkLimitException {
    25	        String user = AuditUser.decode(userHeader);
    26	        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
    27	            throw new ClaimStatusException("A claim in a closed period cannot be re-settled.");
    28	        }
    29	        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user))) {
    30	            throw new ClerkLimitException("Only a steward can re-settle a claim.");
    31	        }
    32	        if (claim.getStatus() != ClaimStatus.SETTLED) {
    33	            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be re-settled.");
    34	        }
    35	        BigDecimal old = claim.getDue();
    36	        BigDecimal due = people.findById(claim.getPersonId())
    37	                .map(p -> new ClaimFigures(rates.findInChain(claim.getSheetId()),
    38	                        grades.gradesOf(p), sheet).openDue(claim))
    39	                .orElse(null);
    40	        claim.setDue(due);
    41	        repository.saveAndFlush(claim);
    42	        return new Resettled(old, due);
    43	    }
    44	}
