    10	/**
    11	 * Shares the claim with another person on the sheet. A SETTLED, VOID or DELETED claim cannot be shared; nor can it be
    12	 * shared with its own person, with a person already holding a share of it, or so its shares total more than 100.00.
    13	 */
    14	public class ApplyShare {
    15	    public void apply(@Val ShareRequest request, @Val Claim claim, PersonRepository people, ClaimRepository repository,
    16	            Out<Person> holder) throws ClaimStatusException, InvalidClaimException {
    17	        ClaimStatus status = claim.getStatus();
    18	        if (status == ClaimStatus.SETTLED || status == ClaimStatus.VOID || status == ClaimStatus.DELETED) {
    19	            throw new ClaimStatusException("A " + status + " claim cannot be shared.");
    20	        }
    21	        Long personId = Long.valueOf(request.personId());
    22	        Person person = people.findById(personId).filter(p -> p.getSheetId().equals(claim.getSheetId()))
    23	                .orElseThrow(() -> new InvalidClaimException("No such person on the sheet."));
    24	        if (personId.equals(claim.getPersonId())) {
    25	            throw new InvalidClaimException("A claim cannot be shared with its own person.");
    26	        }
    27	        List<ClaimShares.Share> shares = ClaimShares.of(claim);
    28	        if (shares.stream().anyMatch(s -> s.personId().equals(personId))) {
    29	            throw new InvalidClaimException(person.getName() + " already holds a share of this claim.");
    30	        }
    31	        BigDecimal share = new BigDecimal(request.share());
    32	        if (ClaimShares.total(shares).add(share).compareTo(new BigDecimal("100.00")) > 0) {
    33	            throw new InvalidClaimException("A claim's shares cannot total more than 100.00.");
    34	        }
    35	        claim.setShares(ClaimShares.adding(claim, personId, share));
    36	        repository.saveAndFlush(claim);
    37	        holder.set(person);
    38	    }
    39	}
