    19	/**
    20	 * Splits an amount (more than 0.00 and less than the claim's amount) off an OPEN claim. The claim keeps the rest and
    21	 * loses any figure a statement bound it to; a new OPEN claim of the same person gets the split-off amount, the same
    22	 * date and note, no number (it is numbered when it is settled), the signed-in user as who opened it, a due-by fixed now from
    23	 * the terms in force on the date, the original's number as the one it was split from, and the original's tags. A user whose role the sheet's permission matrix does not allow to open a claim cannot split one (the split opens
    24	 * the new claim). A PENDING, deferred, settled
    25	 * or any other non-OPEN claim, or one whose due-by is in a closed period, is refused. The new claim is a late entry when that period is soft-closed. Returns the split, for the audit.
    26	 */
    27	public class ApplySplit {
    28	
    29	    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");
    30	
    31	    public Split apply(@Val Claim claim, @Val Sheet sheet, ClaimRepository repository, EntityManager entityManager,
    32	            PeriodRepository periods, PersonRepository people, PersonGradeRepository grades, RateRepository rates,
    33	            ClaimLogRepository log, HolidayRepository holidays, RoleRepository roles,
    34	            @RequestHeader(name = "X-User", required = false) String userHeader,
    35	            @RequestParam(name = "amount", required = false) String amountParam) throws ClaimStatusException {
    36	        String user = AuditUser.decode(userHeader);
    37	        String amountField = amountParam == null ? "" : amountParam.trim();
    38	        if (!AMOUNT.matcher(amountField).matches()) {
    39	            throw new ClaimStatusException("The amount to split off must be a number with up to two decimals.");
    40	        }
    41	        BigDecimal amount = new BigDecimal(amountField).setScale(2);
    42	        String role = roles.roleOf(claim.getSheetId(), user);
    43	        if (!sheet.allows("open", role)) {
    44	            throw new ClaimStatusException("A " + role + " cannot open a claim, so cannot split one.");
    45	        }
    46	        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
    47	            throw new ClaimStatusException("A claim in a closed period cannot be split.");
    48	        }
    49	        // Lock the sheet first, then re-read the claim so a concurrent change is seen.
    50	        repository.lockSheet(claim.getSheetId());
    51	        entityManager.refresh(claim);
    52	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheet.getToday())) {
    53	            throw new ClaimStatusException("Only an OPEN claim that is not deferred can be split.");
    54	        }
    55	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
    56	            throw new ClaimStatusException("The amount to split off must be more than 0.00 and less than the claim's.");
    57	        }
    58	        int terms = people.findById(claim.getPersonId())
    59	                .map(p -> sheet.termsFor(p.termsOn(sheet.getToday()), grades.gradesOf(p).on(sheet.getToday()), sheet.getToday())).orElse(0);
    60	        LocalDate dueBy = holidays.dueBy(claim.getSheetId(), claim.getDate(), terms);
    61	        claim.setAmount(claim.getAmount().subtract(amount));
    62	        claim.bind(false, null);
    63	        repository.saveAndFlush(claim);
    64	
    65	        Claim made = new Claim(claim.getSheetId(), claim.getPersonId(), amount, claim.getDate(), claim.getNote(), null);
    66	        made.setStatus(ClaimStatus.OPEN);
    67	        made.setOpenedBy(user);
    68	        made.setSplitFrom(claim.getNumber());
    69	        made.setTags(claim.getTags());
    70	        made.fixDue(claim.getDate(), terms, holidays.datesOf(claim.getSheetId()));
    71	        made.setLateEntry(periods.isSoftClosedOn(claim.getSheetId(), dueBy));
    72	        made = repository.saveAndFlush(made);
    73	        entityManager.refresh(made);
    74	        ClaimRules.log(made, sheet, log, people, rates, grades, user);
    75	        return new Split(made);
    76	    }
    77	}
