    14	/**
    15	 * The names and aliases in use on the other sheets of a sheet's tree: its ancestors (its parent, its parent's parent,
    16	 * and so on) and its descendants (its children, their children, and so on), among the sheets that exist. A name or
    17	 * alias may not be used on a sheet when any of them already uses it, ignoring case.
    18	 */
    19	@Service
    20	public class TreeNames {
    21	    private final SheetRepository sheets;
    22	    private final PersonRepository people;
    23	    private final PersonAliasRepository aliases;
    25	    public TreeNames(SheetRepository sheets, PersonRepository people, PersonAliasRepository aliases) {
    26	        this.sheets = sheets;
    27	        this.people = people;
    28	        this.aliases = aliases;
    29	    }
    31	    /** The ids of the other sheets of the sheet's tree. */
    32	    public Set<String> treeOf(String sheetId) {
    33	        Set<String> tree = new LinkedHashSet<>();
    34	        Set<String> seen = new HashSet<>();
    35	        seen.add(sheetId);
    36	        for (String id = parentOf(sheetId); id != null && seen.add(id); id = parentOf(id)) {
    37	            if (sheets.existsById(id)) {
    38	                tree.add(id);
    39	            }
    40	        }
    41	        Deque<String> todo = new ArrayDeque<>(List.of(sheetId));
    42	        Set<String> visited = new HashSet<>(List.of(sheetId));
    43	        while (!todo.isEmpty()) {
    44	            for (String child : sheets.childrenOf(todo.pop())) {
    45	                if (visited.add(child)) {
    46	                    tree.add(child);
    47	                    todo.add(child);
    48	                }
    49	            }
    50	        }
    51	        tree.remove(sheetId);
    52	        return tree;
    53	    }
    55	    /** The names and aliases, lower-cased, in use on the other sheets of the sheet's tree. */
    56	    public Set<String> usedAround(String sheetId) {
    57	        Set<String> tree = treeOf(sheetId);
    58	        Set<String> used = new HashSet<>();
    59	        if (tree.isEmpty()) {
    60	            return used;
    61	        }
    62	        people.findBySheetIdIn(tree).forEach(p -> used.add(key(p.getName())));
    63	        aliases.findBySheetIdIn(tree).forEach(a -> used.add(key(a.getAlias())));
    64	        return used;
    65	    }
    67	    /** Whether any of the names is in use, ignoring case, on another sheet of the sheet's tree. */
    68	    public boolean usedAround(String sheetId, Collection<String> names) {
    69	        Set<String> used = usedAround(sheetId);
    70	        return names.stream().anyMatch(n -> used.contains(key(n)));
    71	    }
    73	    /** Whether the name is in use, ignoring case, on another sheet of the sheet's tree. */
    74	    public boolean usedAround(String sheetId, String name) {
    75	        return usedAround(sheetId, List.of(name));
    76	    }
    78	    public static String key(String name) {
    79	        return name.toLowerCase(Locale.ROOT);
    80	    }
    82	    private String parentOf(String sheetId) {
    83	        return sheets.parentsOf(sheetId).stream().filter(p -> p != null).findFirst().orElse(null);
    84	    }
    85	}
