20	     1	import type { ComponentType } from 'react';
21	     2	
22	     3	// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
23	     4	// pulls in every feature's contribution file, and those files reach a slot definition, which
24	     5	// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
25	     6	// defs -> Slot -> registry) is what stops the module graph forming a cycle.
26	     7	
27	     8	export type Registered = {
28	     9	  slot: string;
29	    10	  order: number;
30	    11	  /** Source file — the React key and the deterministic tie-break for equal `order`. */
31	    12	  from: string;
32	    13	  Component: ComponentType<never>;
33	    14	};
34	    15	
35	    16	const contributions: Registered[] = [];
36	    17	
37	    18	/** Called once per contribution at startup, by slots/discover.ts. */
38	    19	export function register(entry: Registered): void {
39	    20	  contributions.push(entry);
40	    21	}
41	    22	
42	    23	export function forSlot(id: string): Registered[] {
43	    24	  return contributions
44	    25	    .filter((c) => c.slot === id)
45	    26	    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
