59	    12	//   2. render it         ->  <ProjectDetail.Slot projectId={id} />
60	    13	//   3. fill it           ->  features/projects/notes.slot.tsx
61	    14	//        export const contribution = ProjectDetail.fill({ order: 30, Component: ProjectNotes });
62	    15	//
63	    16	// This file, slots/registry.ts and slots/discover.ts implement that mechanism; a region is
64	    17	// declared by a file under slots/defs/.
65	    18	
66	    19	export type Contribution<Ctx> = {
67	    20	  /** Lower renders first; equal orders fall back to file path, so the order is always stable. */
68	    21	  order?: number;
69	    22	  Component: ComponentType<Ctx>;
70	    23	};
71	    24	
72	    25	export type SlotDef<Ctx extends object> = {
73	    26	  id: string;
74	    27	  /** Renders the region. Its props ARE the context handed to every contribution. */
75	    28	  Slot: (ctx: Ctx) => ReactElement;
76	    29	  /** A feature wraps its contribution in this, to be typed against the region's context. */
77	    30	  fill: (contribution: Contribution<Ctx>) => Contribution<Ctx> & { slot: string };
78	    31	};
79	    32	
80	    33	export function defineSlot<Ctx extends object = Record<string, never>>(id: string): SlotDef<Ctx> {
81	    34	  return {
82	    35	    id,
83	    36	    // A Fragment, never a wrapper element: a slot must be usable inside <thead>/<tr> (columns and
84	    37	    // row actions are slots too), where a stray <div> would be invalid markup.
85	    38	    Slot: (ctx: Ctx) =>
86	    39	      createElement(
87	    40	        Fragment,
88	    41	        null,
89	    42	        forSlot(id).map((c) =>
90	    43	          createElement(c.Component as ComponentType<Ctx>, { key: c.from, ...ctx }),
91	    44	        ),
92	    45	      ),
