    24	/** Merges a grade into another: only a steward may, and not into a retired grade. Records GRADE_MERGED, then gives
    25	 *  every person (in list order) whose grade in force on the sheet's today is the merged grade the other from the
    26	 *  sheet's today, each exactly as the person form would save it, with its PERSON_EDITED and rollup lines; then every
    27	 *  grade of theirs on the merged grade, whatever its date (their first grade too), becomes the other. */
    28	public class ApplyGradeMerge {
    29	    public void apply(@Val GradeMergeRequest request, @Val Sheet sheet,
    30	            @RequestHeader(name = "X-User", required = false) String userHeader, RoleRepository roles,
    31	            RetiredGradeRepository retired, AddedGradeRepository added, SheetRepository sheets, PersonRepository people, ClaimRepository claims,
    32	            RateRepository rates, PersonGradeRepository grades, AsOf asOf, EntityManager entityManager, Audit audit,
    33	            Out<GradeMerged> mergedOut) throws InvalidGradeException {
    34	        String user = AuditUser.decode(userHeader);
    35	        if (!Role.STEWARD.equals(roles.roleOf(sheet.getId(), user))) {
    36	            throw new InvalidGradeException("Only a steward can merge a grade.");
    37	        }
    38	        if (!RetiredGrades.isGrade(sheet.getId(), request.from(), added)
    39	                || !RetiredGrades.isGrade(sheet.getId(), request.into(), added)) {
    40	            throw new InvalidGradeException("The grades must be the sheet's grades.");
    41	        }
    42	        if (retired.existsBySheetIdAndGrade(sheet.getId(), request.into())) {
    43	            throw new InvalidGradeException("The grade " + request.into() + " is retired.");
    44	        }
    45	        audit.record("GRADE_MERGED sheet=" + sheet.getId() + " by=" + user
    46	                + " from=" + request.from() + " into=" + request.into());
    47	        int merged = 0;
    48	        for (Person person : people.findListed(sheet.getId())) {
    49	            if (!request.from().equals(grades.gradesOf(person).on(sheet.getToday()))) {
    50	                continue;
    51	            }
    52	            Rollup before = Rollup.of(sheet.getId(), sheets, people, claims, rates, grades, asOf);
    53	            // Every save raises the version, as the person form's does.
    54	            entityManager.lock(person, LockModeType.OPTIMISTIC_FORCE_INCREMENT);
    55	            people.saveAndFlush(person);
    56	            PersonGrade dated = grades.findByPersonIdAndFromDate(person.getId(), sheet.getToday())
    57	                    .orElseGet(() -> new PersonGrade(person.getSheetId(), person.getId(), request.into(), sheet.getToday()));
    58	            dated.setGrade(request.into());
    59	            dated.setMadeOn(sheet.getToday());
    60	            grades.saveAndFlush(dated);
    61	            audit.record(PersonRules.editedLine(person, grades.gradesOf(person).on(sheet.getToday()),
    62	                    person.termsOn(sheet.getToday()), user));
    63	            Rollup.of(sheet.getId(), sheets, people, claims, rates, grades, asOf)
    64	                    .changesSince(before, sheet.getId(), user).forEach(audit::record);
    65	            // Retroactive: every grade of theirs on the merged grade, whatever its date, becomes the other.
    66	            if (request.from().equals(person.getGrade())) {
    67	                person.setGrade(request.into());
    68	                people.saveAndFlush(person);
    69	            }
    70	            for (PersonGrade earlier : grades.findByPersonIdOrderByFromDateAsc(person.getId())) {
    71	                if (request.from().equals(earlier.getGrade())) {
    72	                    earlier.setGrade(request.into());
    73	                    grades.saveAndFlush(earlier);
    74	                }
    75	            }
    76	            merged++;
    77	        }
    78	        mergedOut.set(new GradeMerged(merged));
    79	    }
    80	}
