    26	                .filter(c -> c.getStatus() != ClaimStatus.SETTLED && c.getStatus() != ClaimStatus.VOID)
    27	                .filter(c -> !c.getDueBy().isBefore(date)).toList();
    28	        moved.forEach(c -> c.reworkDueBy(holidays));
    29	        claims.saveAllAndFlush(moved);
