    28	/**
    29	 * For every plan on the sheet, in the order they were added, makes a DRAFT claim with the plan's amount for each plan
    30	 * date (the start, then every N days) up to its end and the sheet's today that has none yet and is not skipped by a
    31	 * pause (on or after the day the plan was paused and before the day it was resumed), dated that day with an
    32	 * empty note, by the claim form's rules: a date the form refuses is skipped, and tried again next time. Each claim is
    33	 * recorded and logged as the claim form records and logs it. A viewer, who changes nothing, makes no claim and gets a
    34	 * count of 0. A plan naming a descendant sheet makes its claims there instead, for the person of the same name on that
    35	 * sheet (none when there is no such person, or the sheet is gone), by that sheet's rules and recorded in its audit; its
    36	 * dates still run up to this sheet's today.
    37	 */
    38	public class GeneratePlans {
    39	    public void generate(@Val Sheet sheet, PlanRepository plans, PlanClaimRepository made, PlanPauseRepository pauses,
    40	            PersonRepository people,
    41	            ClaimRepository claims, PeriodRepository periods, PersonGradeRepository grades, RateRepository rates,
    42	            ClaimLogRepository log, HolidayRepository holidays, RoleRepository roles,
    43	            SheetRepository sheets,
    44	            @RequestHeader(name = "X-User", required = false) String user, Audit audit,
    45	            Out<GeneratedPlans> madeOut) {
    46	        String by = AuditUser.decode(user);
    47	        int count = 0;
    48	        if (Role.VIEWER.equals(roles.roleOf(sheet.getId(), by))) {
    49	            madeOut.set(new GeneratedPlans(count));
    50	            return;
    51	        }
    52	        for (Plan plan : plans.findBySheetIdOrderByIdAsc(sheet.getId())) {
    53	            Person person = people.findByIdAndSheetId(plan.getPersonId(), sheet.getId()).orElse(null);
    54	            Sheet on = sheet;
    55	            if (person != null && plan.getTargetSheetId() != null) {
    56	                on = sheets.findById(plan.getTargetSheetId()).orElse(null);
    57	                String name = person.getName();
    58	                person = on == null ? null
    59	                        : people.findBySheetIdAndNameIgnoreCase(on.getId(), name).stream()
    60	                                .filter(p -> p.getName().equals(name)).findFirst().orElse(null);
    61	            }
    62	            if (person == null) {
    63	                continue;
    64	            }
    65	            Set<LocalDate> done = new HashSet<>();
    66	            made.findByPlanId(plan.getId()).forEach(m -> done.add(m.getOnDate()));
    67	            for (LocalDate date : plan.datesUpTo(sheet.getToday())) {
    68	                if (done.contains(date) || pauses.skips(plan.getId(), date)) {
    69	                    continue;
    70	                }
    71	                Claim claim;
    72	                try {
    73	                    claim = ClaimRules.make(new ClaimInput(plan.getAmount(), date, "", null, null, null), on,
    74	                            person, claims, periods, grades, holidays);
    75	                } catch (InvalidClaimException e) {
    76	                    continue;
    77	                }
    78	                claim = claims.saveAndFlush(claim);
    79	                made.saveAndFlush(new PlanClaim(plan.getId(), date, claim.getId()));
    80	                ClaimRules.auditAdded(claim, person.getName(), by, audit);
    81	                ClaimRules.log(claim, on, log, people, rates, grades, by);
    82	                count++;
    83	            }
    84	        }
    85	        madeOut.set(new GeneratedPlans(count));
    86	    }
    87	}
