    10	/** Reads the plan form from the body, trimmed: an amount of 0.00 or more with up to two decimals, a start and an end
    11	 *  date, the end not before the start, and either every N days, a whole number of at least 1, or a day of the month,
    12	 *  a whole number from 1 to 31 — not both — and a sheet id (blank for none). */
    13	public class ValidatePlan {
    15	    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");
    17	    private static final Pattern EVERY = Pattern.compile("\\d{1,6}");
    19	    private static final Pattern DAY = Pattern.compile("\\d{1,2}");
    21	    public void validate(@RequestBody(required = false) PlanRequest request, Out<PlanInput> body)
    22	            throws InvalidPlanException {
    23	        String amount = trim(request == null ? null : request.amount());
    24	        String every = trim(request == null ? null : request.every());
    25	        String day = trim(request == null ? null : request.day());
    26	        String sheet = trim(request == null ? null : request.sheet());
    27	        if (!AMOUNT.matcher(amount).matches()) {
    28	            throw new InvalidPlanException("The amount must be 0.00 or more with up to two decimals.");
    29	        }
    30	        Integer everyDays = null;
    31	        Integer monthDay = null;
    32	        if (!day.isEmpty()) {
    33	            if (!every.isEmpty()) {
    34	                throw new InvalidPlanException("A plan runs every N days or on a day of the month, not both.");
    35	            }
    36	            if (!DAY.matcher(day).matches() || Integer.parseInt(day) < 1 || Integer.parseInt(day) > 31) {
    37	                throw new InvalidPlanException("The day must be a whole number from 1 to 31.");
    38	            }
    39	            monthDay = Integer.parseInt(day);
    40	        } else {
    41	            if (!EVERY.matcher(every).matches() || Integer.parseInt(every) < 1) {
    42	                throw new InvalidPlanException("Every must be a whole number of days, at least 1.");
    43	            }
    44	            everyDays = Integer.parseInt(every);
    45	        }
    46	        LocalDate start = date(request == null ? null : request.start(), "start");
    47	        LocalDate end = date(request == null ? null : request.end(), "end");
    48	        if (end.isBefore(start)) {
    49	            throw new InvalidPlanException("The end must not be before the start.");
    50	        }
    51	        body.set(new PlanInput(new BigDecimal(amount).setScale(2), start, everyDays, monthDay, end,
    52	                sheet.isEmpty() ? null : sheet));
    53	    }
    55	    private static String trim(String field) {
    56	        return field == null ? "" : field.trim();
    57	    }
    59	    private static LocalDate date(String field, String what) throws InvalidPlanException {
    60	        try {
    61	            return LocalDate.parse(trim(field));
    62	        } catch (DateTimeParseException e) {
    63	            throw new InvalidPlanException("The " + what + " must be a date.");
    64	        }
    65	    }
    66	}
