    18	/** Gives the plan's new amount to the claims it generated that are still DRAFT, each as the claim form would edit it
    19	 *  (recording who last edited it and writing CLAIM_EDITED), in the order they were generated. A draft the claim form
    20	 *  would refuse the amount for keeps its own: one locked by another user, one whose due-by is in a closed period, one
    21	 *  whose lines total another amount, and one dated after its person's retirement date. Claims in any other status keep
    22	 *  theirs. */
    23	public class EditPlanDrafts {
    24	    public void edit(@Val Plan plan, PlanClaimRepository planClaims, ClaimRepository claims, PeriodRepository periods,
    25	            ClaimLineRepository lines, PersonRepository people,
    26	            @RequestHeader(name = "X-User", required = false) String userHeader, Audit audit) {
    27	        String user = AuditUser.decode(userHeader);
    28	        BigDecimal amount = plan.getAmount();
    29	        planClaims.findByPlanId(plan.getId()).stream().sorted(Comparator.comparing(PlanClaim::getClaimId))
    30	                .forEach(made -> claims.findById(made.getClaimId()).ifPresent(claim -> {
    31	                    if (claim.getStatus() != ClaimStatus.DRAFT || claim.isLockedFor(user) || periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
    32	                        return;
    33	                    }
    34	                    BigDecimal lined = lines.totalOf(claim);
    35	                    if (lined != null && amount.compareTo(lined) != 0) {
    36	                        return;
    37	                    }
    38	                    Person person = people.findById(claim.getPersonId()).orElse(null);
    39	                    if (person != null && person.retiredOn(claim.getDate())) {
    40	                        return;
    41	                    }
    42	                    claim.setAmount(amount);
    43	                    claim.setEditedBy(user);
    44	                    claims.saveAndFlush(claim);
    45	                    audit.record(ClaimAudit.line("CLAIM_EDITED", claim, person == null ? "" : person.getName(), user));
    46	                }));
    47	    }
