978	      claim
979	        ? putJson<Claim>(`${claimsPath(sheet)}/${claim.id}`, body, user)
980	        : postJson<Claim>(personClaimsPath(sheet, person.id), body, user),
981	    onSuccess: async () => {
982	      await queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
983	      if (claim) {
984	        setEditing(undefined);
985	      } else {
986	        setAmount('');
987	        setDate('');
988	        setNote('');
989	        setCorrects('');
990	        setRef('');
991	        setTags('');
992	      }
993	    },
994	    onError: (error) => {
995	      if (claim) onRefused(error, claim.id);
996	    },
997	  });
998	  const submit = useSubmitOnce(save);
