1020	      }}
1021	    >
1022	      <input
1023	        data-testid="claim-form-amount"
1024	        placeholder="Amount"
1025	        inputMode="decimal"
1026	        value={amount}
1027	        onChange={(e) => { setAmount(e.target.value); save.reset(); fromTemplate.reset(); clearRefusal(); }}
1028	      />
1029	      <input
1030	        data-testid="claim-form-date"
1031	        placeholder={today ?? 'YYYY-MM-DD'}
1032	        value={date}
