1034	      />
1035	      <input
1036	        data-testid="claim-form-note"
1037	        placeholder="Note"
1038	        value={note}
1039	        onChange={(e) => { setNote(e.target.value); save.reset(); fromTemplate.reset(); clearRefusal(); }}
1040	      />
1041	      <input
1042	        data-testid="claim-form-corrects"
